//源表：battle_fury_layer.xlsx（愈战愈勇层数表）
#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<int, battle_fury_layer> battle_fury_layerData;
        public battle_fury_layer Getbattle_fury_layerConfig(int key)
        {
            return ConfigBinary.Require(battle_fury_layerData, key, "battle_fury_layer");
        }
        private void Loadbattle_fury_layerConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("battle_fury_layer"))
            {
                int count = r.ReadInt32();
                battle_fury_layerData = new Dictionary<int, battle_fury_layer>(count);
                for (int i = 0; i < count; i++)
                {
                    battle_fury_layer row;
                    row.key = r.ReadInt32();
                    row.deathCount = r.ReadInt32();
                    row.buffLayerCount = r.ReadInt32();
                    battle_fury_layerData.Add(row.key, row);
                }
            }
        }
    }
    public struct battle_fury_layer
    {
        public int key;  // 主键
        public int deathCount;  // 死亡次数
        public int buffLayerCount;  // buff层数
    }
}
